INSERT INTO tajik_bhava_phal (rule_id,house,shloka,category,cond_text,phal_text,note_text,language) VALUES
('B01_01',1,'१','shubh','कोई भाव अपने स्वामी और शुभग्रह से दृष्ट या युक्त हो।','उस भाव की वृद्धि होती है।','सामान्य मूल-सूत्र — सभी भावों पर लागू।','hi'),
('B01_02',1,'१','ashubh','भाव पापग्रहों से दृष्ट या युक्त हो।','उस भाव का नाश होता है।','','hi'),
('B01_03',1,'१','mishrit','भाव शुभ तथा पाप दोनों से दृष्ट/युक्त हो।','मिश्रित (शुभाशुभ) फल।','','hi'),
('B01_04',1,'२','shubh','वर्षलग्नेश पंचवर्गीय बल से बलवान् हो।','शरीर-सुख, आरोग्य, द्रव्य-लाभ और आनन्द।','','hi'),
('B01_05',1,'२','mishrit','वर्षलग्नेश मध्यम बली हो।','कम सुख और कम धन।','','hi'),
('B01_06',1,'२','ashubh','वर्षलग्नेश अल्प बली हो।','क्लेश अधिक; बराबर विपत्तियाँ आती रहती हैं।','','hi'),
('B01_07',1,'३','ashubh','पंचाधिकारियों (जन्मलग्नेश, वर्षलग्नेश, मुन्थापति, त्रिराशिपति, दिन/रात्रि-पति) में से किसी अधिकार को प्राप्त सूर्य नष्टबली हो।','त्वचा-रोग से कष्ट, नेत्र-रोग से पीड़ा, उत्साह-हीनता, माता-पिता से अनादर।','','hi'),
('B01_08',1,'३','ashubh','अधिकार-प्राप्त चन्द्रमा नष्टबली हो।','नेत्र व वांछित कार्य नष्ट; दरिद्रता, सर्वत्र अनादर, स्त्रियों से कलह, आधि-व्याधि का सदा भय।','','hi'),
('B01_09',1,'४','ashubh','अधिकार-प्राप्त मङ्गल हीनबली हो।','मन सदा चलायमान; चोर आदि से भयभीत।','','hi'),
('B01_10',1,'४','ashubh','अधिकार-प्राप्त बुध नष्टबली हो।','मोह (मतिभ्रम) और पराभव।','','hi'),
('B01_11',1,'४','ashubh','अधिकार-प्राप्त बृहस्पति नष्टबली हो।','धर्म का क्षय; कन्द-मूल-फल खाकर बड़े कष्ट से जीवन-निर्वाह।','','hi'),
('B01_12',1,'५','ashubh','अधिकार-प्राप्त शुक्र बलहीन हो।','विलास-क्रीड़ा व सौख्य का नाश; स्त्रियों के साथ कलह।','','hi'),
('B01_13',1,'५','ashubh','अधिकार-प्राप्त शनि नष्टबली हो।','नौकरों से क्लेश; वातरोग की पीड़ा बनी रहती है।','','hi'),
('B01_14',1,'६','ashubh','वर्षलग्न पापग्रहों से युक्त हो और शुभग्रहों से न दृष्ट, न युक्त हो।','विवाद; चोरादिकों से ठगा जाना; दुष्ट भोजन आदि फल।','','hi'),
('B01_15',1,'७','shubh','जन्मलग्नेश, वर्षलग्नेश, अष्टमेश और वर्षेश-मुन्थेश — ये बलिष्ठ होकर ६, ८, १२ भावों में स्थित न हों।','सम्पूर्ण वर्ष शुभ; अतुल सौख्य, यश और धन।','','hi'),
('B01_16',1,'७','ashubh','उक्त स्वामी बली होकर ६, ८, १२ में स्थित हों।','दुःख देते हैं।','','hi'),
('B01_17',1,'७','ashubh','उक्त स्वामी बलरहित होकर ६, ८, १२ में हों।','दुःख तथा चोरादिकों से भय।','','hi'),
('B01_18',1,'७','mishrit','उक्त चारों शुभग्रहों से न देखे जाएँ / देखे जाएँ।','न देखे जाएँ तो सम्पूर्ण वर्ष अशुभ; शुभग्रह देखते हों तो शुभ फल ही होता है।','अन्तर्निहित भंग-नियम।','hi'),
('B01_19',1,'८','ashubh','जन्मकाल का धनयोग-कर्ता ग्रह और धनेश — ये दोनों वर्ष में नष्टबली हों।','धन नष्ट हो जाता है; धरोहर रखने वाला मुकर जाता है ("तुम्हारा कुछ नहीं है")।','','hi'),
('B01_20',1,'९','ashubh','जन्मकाल में सब भावों के फलदाता स्वामी/पोषक ग्रह वर्षकाल में बलहीन हों।','उन-उन भावों के फल नष्ट — भाव अपना फल नहीं देते।','व्यापक सूत्र — सभी भावों पर।','hi'),
('B02_01',2,'१','shubh','जन्म में बृहस्पति धनेश होकर वर्षलग्न से दूसरे भाव में स्थित हो और लग्नेश से इत्थशाल करे।','वर्ष-भर धन की प्राप्ति।','','hi'),
('B02_02',2,'१','ashubh','वही बृहस्पति लग्नेश को छोड़कर किसी पापग्रह से ईसराफ योग करे।','वर्ष-भर धन-धान्य की हानि।','','hi'),
('B02_03',2,'२','shubh','जन्मकाल का बृहस्पति दूसरे स्थान को देखता हो और वही वर्षेश होकर बलवान् हो।','उस वर्ष अनायास धन-प्राप्ति।','','hi'),
('B02_04',2,'३','shubh','बृहस्पति जिस भाव का स्वामी हो, वर्षप्रवेश में उसी भाव में हो और लग्नेश से इत्थशाल करे।','उसी भाव से उत्पन्न सुख मिलता है।','','hi'),
('B02_05',2,'४','shubh','जन्मकाल में बृहस्पति जिस भाव को देखता हो, वही (गुरु) वर्षेश हो।','उस भाव का सुख प्राप्त होता है।','','hi'),
('B02_06',2,'५','mishrit','बुध जन्म-षष्ठेश होकर वर्षलग्न से छठे भाव में हो।','थोड़ा धन मिलता है।','','hi'),
('B02_07',2,'५','ashubh','बृहस्पति पापग्रहों से पीड़ित होकर वर्षलग्न से आठवें या धन (दूसरे) भाव में हो।','अवश्य राजदण्ड।','','hi'),
('B02_08',2,'६','shubh','बृहस्पति धन-भाव में हो और शुभग्रह देखें या युक्त हों।','राज्य और सुख दोनों।','','hi'),
('B02_09',2,'६','shubh','वर्षलग्न में स्थित बृहस्पति मुन्था को देखे।','विशेष रूप से राज्य व सुख।','','hi'),
('B02_10',2,'७','shubh','शुक्र वर्षेश होकर धन-स्थान में हो; शुभग्रह देखें या युक्त हों।','बहुत धन-धान्य।','','hi'),
('B02_11',2,'७','ashubh','धन-स्थान में धनेश और लग्नेश का ईसराफ योग हो।','धन-सौख्य का विनाश।','','hi'),
('B02_12',2,'८','shubh','बुध सबल व वर्षेश होकर धन-भाव में हो; शुभग्रह देखें या युक्त हों।','लेखन व ज्ञान (व्याख्यान आदि) उद्यम से धन-प्राप्ति।','','hi'),
('B02_13',2,'८','shubh','जन्मलग्न में स्थित शुभग्रह वर्षकुण्डली के धन-भाव में हों।','धन-लाभ।','','hi'),
('B02_14',2,'९','shubh','माल-सहम (धन-सहम) और धन-भाव दोनों बुध, बृहस्पति व शुक्र से युक्त या दृष्ट हों।','बहुत धन तथा अपने कुल का राज्य (धनाधिपत्य)।','यवन-भाषा में "माल" = धन।','hi'),
('B02_15',2,'१०','shubh','धन-भावेश और अर्थ-सहमेश दोनों बली होकर शुभग्रहों की मित्र-दृष्टि (३,५,९,११) से दृष्ट हों।','सुख तथा बहुत धन-लाभ।','','hi'),
('B02_16',2,'१०','mishrit','वे ही दोनों शुभग्रहों की शत्रु-दृष्टि (१,४,७,१०) से दृष्ट हों।','बड़े यत्न (परिश्रम) से धन मिलता है।','','hi'),
('B02_17',2,'११','shubh','धनेश और वर्षलग्नेश में मित्र-दृष्टि से इत्थशाल हो।','बिना परिश्रम धन-प्राप्ति।','','hi'),
('B02_18',2,'११','ashubh','उन दोनों में ईसराफ योग हो।','धन का नाश; कुमार्ग-वर्तन से सदा भयभीत।','','hi'),
('B02_19',2,'१२','shubh','जन्मकालीन बृहस्पति की राशि ही वर्षलग्न हो और वह शुभग्रहों या अपने स्वामी से दृष्ट/युक्त हो।','आरोग्य, स्वामित्व (आधिपत्य) तथा धन।','','hi'),
('B02_20',2,'१३','shubh','जन्म-समय सूर्य लग्न में हो और वर्षप्रवेश के समय वही धन-स्थान में हो।','धन तथा सुख।','','hi'),
('B02_21',2,'१३','ashubh','धन-भाव में शनि हो।','कार्य नष्ट; थोड़ा लाभ देकर धन खर्च कराता है।','','hi'),
('B02_22',2,'१४','shubh','धन-भाव में स्थित शनि बृहस्पति से युक्त हो।','भाई-बन्धुओं से सुख (ऐश्वर्य)।','शुभग्रह-दर्शन से ऐश्वर्य।','hi'),
('B02_23',2,'१४','ashubh','धन-लाभ-कारक ग्रह पापग्रहों से युक्त व दृष्ट हो।','सम्पूर्ण फल नष्ट — धन की हानि।','','hi'),
('B02_24',2,'१५–१८','mishrit','जन्म का धनेश बृहस्पति वर्षप्रवेश में वर्षेश हो — वह जिस भाव में बैठा हो उसी का फल देता है।','लग्न=आत्मसुख; २=सुवर्ण-चाँदी लाभ; ३=भाई-बन्धुओं से लाभ; ४=माता-पिता, खेती, ग्राम से सुख; ५=मित्रों व पुत्रों से सौख्य; ६=मृत्यु(शत्रु-हानि); ७=स्त्री-सम्बन्धी सुख; ८=मृत्यु; ९=मार्ग में द्रव्य-लाभ; १०=राजा से लाभ; ११=राजकुल से धन-लाभ; १२=परमार्थ में अधिक व्यय।','भाव-स्थान-सारिणी; सुधी जन विचार कर फल कहें।','hi'),
('B03_01',3,'१','shubh','वर्षेश सूर्य या शुक्र बलिष्ठ हो और पापग्रहों से युक्त/दृष्ट न हो।','भाइयों से सुख।','','hi'),
('B03_02',3,'१','ashubh','वर्षेश सूर्य तथा शुक्र निर्बल होकर पापग्रहों से युक्त/दृष्ट हों।','भाइयों में परस्पर झगड़ा।','','hi'),
('B03_03',3,'२','ashubh','तृतीयेश वर्षेश सूर्य के सान्निध्य से अस्त हो या दुष्ट स्थान में हो।','कलहादिकों से दुःख।','','hi'),
('B03_04',3,'२','ashubh','सूर्य/शुक्र में से कोई वर्ष का स्वामी होकर अस्तंगत या नष्टबली हो।','कलह कराता है।','','hi'),
('B03_05',3,'२','ashubh','बृहस्पति अधम (हीन) बल से युक्त होकर तीसरे भाव में हो।','भाइयों से वैर।','','hi'),
('B03_06',3,'२','ashubh','वर्षेश तीसरे भाव के स्वामी (पराक्रमेश) से ईसराफ योग करे।','शरीर को भारी कष्ट; निर्बल होकर बन्धुओं से लड़ाई।','','hi'),
('B03_07',3,'३','shubh','लग्नेश या वर्षेश में से किसी का तृतीयेश से इत्थशाल हो।','भाइयों से सुख।','','hi'),
('B03_08',3,'३','shubh','बृहस्पति तीसरे भाव में हो।','भाइयों से सुख।','','hi'),
('B03_09',3,'३','ashubh','तीसरे भाव में मङ्गल के साथ पुष्ट (शुक्ल) चन्द्रमा हो और दोनों को बृहस्पति न देखे, न युक्त हो।','भाइयों से लड़ाई।','','hi'),
('B03_10',3,'४','shubh','तृतीयेश पाँच अधिकारों में से किसी अधिकार में हो, तीसरे भाव में बैठा हो और वर्षेश या लग्नेश से इत्थशाल करे।','उसके भाइयों को उससे सुख मिलता है।','','hi'),
('B03_11',3,'५','ashubh','तृतीयेश के साथ पापग्रह ईसराफ योग करे।','भाइयों में कलह।','','hi'),
('B03_12',3,'५','ashubh','शनि मङ्गल के घर (मेष/वृश्चिक) की राशि का होकर तीसरे भाव में हो।','भाई रोग से पीड़ित।','','hi'),
('B03_13',3,'५','ashubh','मङ्गल बुध के घर (मिथुन/कन्या) की राशि का होकर तीसरे स्थान में हो।','भाइयों को रोग घर दबाता है।','','hi'),
('B03_14',3,'६','shubh','शनि के घर (मकर/कुम्भ) में मङ्गल हो, बुध मङ्गल के घर (मेष/वृश्चिक) में हो और तीसरे स्थान में शुभग्रह हों/शुभग्रह देखें।','भाइयों को बहुत सौख्य।','','hi'),
('B03_15',3,'७','shubh','बुध और शुक्र दोनों बलवान् होकर तीसरे भाव में हों और बृहस्पति बलवान् होकर तीसरे घर में हो।','जातक के भाई-बन्धु-बान्धवों को सुखदायक।','','hi'),
('B03_16',3,'७','shubh','बुध अपने घर व अपनी हद्दा आदि को प्राप्त होकर लग्न में स्थित हो।','भाइयों की सब प्रकार से वृद्धि।','','hi'),
('B03_17',3,'८','ashubh','तीसरा भाव पापग्रहों से युक्त हो और उसे भ्रातृ-सहमेश तथा सहज-भाव का स्वामी न देखें।','भाई को दुःख।','','hi'),
('B03_18',3,'८','ashubh','भ्रातृ-सहम पापग्रहों से युक्त हो और उसे उसका स्वामी तथा तृतीयेश न देखें।','भाइयों को कष्ट।','','hi'),
('B03_19',3,'८','ashubh','भ्रातृ-सहमेश व पराक्रमेश दोनों अस्तंगत होकर दुष्ट स्थान में हों।','भाइयों की हानि।','','hi'),
('B03_20',3,'९','ashubh','तृतीयेश से सातवें भाव में वर्षेश अथवा लग्नस्वामी बैठा हो।','भाइयों के साथ युद्ध।','','hi'),
('B03_21',3,'९','shubh','जन्म का तृतीयेश वर्ष में सहज-भाव में स्थित हो और शुभग्रह देखें।','भाइयों को सब तरह से सन्तोष।','','hi'),
('B04_01',4,'१','ashubh','वर्षप्रवेश के समय सूर्य पापग्रहों से युक्त या दृष्ट होकर चौथे भाव में हो।','पिता को पीड़ा।','','hi'),
('B04_02',4,'१','ashubh','चन्द्रमा पापयुक्त/पापदृष्ट होकर चौथे भाव में हो।','माता को पीड़ा।','','hi'),
('B04_03',4,'१','ashubh','सूर्य-चन्द्र दोनों पापयुक्त/पापदृष्ट होकर चतुर्थ में हों।','माता-पिता दोनों को दुःख।','','hi'),
('B04_04',4,'१','ashubh','जन्म-समय सूर्य के साथ शनि विराजमान हो।','अपमान; पिता के साथ वैर और कलह।','','hi'),
('B04_05',4,'२','ashubh','जन्म-चन्द्रमा की राशि में वर्ष के समय शनि हो।','माता के साथ वैर-कलह।','','hi'),
('B04_06',4,'२','shubh','चतुर्थ स्थान का स्वामी चौथे घर में ही बैठा हो।','माता-पिता को सुख।','','hi'),
('B04_07',4,'२','shubh','चतुर्थेश उत्तम बली होकर लग्नेश के साथ इत्थशाल करे।','माता-पिता को सुखदायक।','','hi'),
('B04_08',4,'३','ashubh','जन्म या वर्ष का सुखेश (चतुर्थेश) नष्टबली हो।','माता-पिता को दुःख।','','hi'),
('B04_09',4,'३','mrityu','मातृ-सहम व पितृ-सहम पापग्रहों से पीड़ित होकर चौथे स्थान में हों।','माता-पिता का नाश।','','hi'),
('B04_10',4,'३','mrityu','मातृ-पितृ सहम दोनों नष्ट(बली) अथवा अस्तादि दोषों से युक्त हों।','माता-पिता का नाश।','','hi'),
('B04_11',4,'४','ashubh','चौथे घर या चतुर्थेश (के पद) के साथ शनि-मङ्गल हों और वे शुभग्रहों से युक्त/दृष्ट न हों।','माता-पिता को कष्ट।','कुन्तला के अनुसार शुभ-दृष्टि होने पर क्लेश नहीं होता।','hi'),
('B04_12',4,'५','shubh','माता-पिता के सहम चतुर्थ भाव के स्वामी से इत्थशाल करें।','माता-पिता को सुख।','','hi'),
('B04_13',4,'५','ashubh','मातृ/पितृ-सहम का आठवें घर के स्वामी (अष्टमेश) से इत्थशाल हो।','माता-पिता को बड़ा दुःख और भय।','','hi'),
('B05_01',5,'१','shubh','बृहस्पति वर्षेश होकर पाँचवें या ग्यारहवें स्थान में हो।','पुत्रों का सुखकारी।','','hi'),
('B05_02',5,'१','shubh','सूर्य, मङ्गल, बुध, शुक्र में से कोई वर्षेश होकर ५वें/११वें भाव में हो।','पुत्रों का सुखकारी।','','hi'),
('B05_03',5,'१','ashubh','बृहस्पति, सूर्य, मङ्गल, बुध, शुक्र — ये पाँचों पापग्रहों से पीड़ित हों।','पुत्रों को दुःख देते हैं।','','hi'),
('B05_04',5,'२','shubh','पाँचवें भाव में बलसहित पुत्र-सहम हो।','पुत्रों की प्राप्ति।','','hi'),
('B05_05',5,'२','shubh','पाँचवें घर में वर्षेश स्थित हो और शुभग्रह देखें।','बालकों को बहुत सुख।','','hi'),
('B05_06',5,'२','shubh','मङ्गल-सहित बुध (सबल) शुभग्रहों की राशि में, शुभग्रह से दृष्ट, ५वें या ११वें भाव में हो।','पुत्रों को सुख।','','hi'),
('B05_07',5,'२','ashubh','मङ्गल-सहित बुध बलहीन होकर उक्त स्थानों में न हो।','पुत्र को रोग।','','hi'),
('B05_08',5,'३','shubh','जन्म में बृहस्पति जिस राशि में हो, वह राशि (वर्ष में) बलिष्ठ हो और गुरु ५वें घर में हो।','पुत्रों को सुख।','','hi'),
('B05_09',5,'३','shubh','वर्ष में मङ्गल या बुध वर्षेश होकर पाँचवें भाव में हो।','पुत्रदायक (पुत्र-प्राप्ति)।','','hi'),
('B05_10',5,'४','shubh','जन्म-समय बृहस्पति जिस स्थान (राशि) में हो, वही स्थान वर्षलग्न हो।','पुत्र प्राप्त होता है।','इसी तरह बुध-शुक्र के स्थान से भी पुत्र-प्राप्ति।','hi'),
('B05_11',5,'४','shubh','जन्म-समय शनि तथा मङ्गल जिस राशि में बैठे हों, वह राशि वर्षप्रवेश-लग्न में या पंचम भाव में हो।','निश्चय करके पुत्रों की प्राप्ति।','','hi'),
('B05_12',5,'५','shubh','पुण्य-सहम शुभग्रहों की दृष्टि से युक्त होकर पंचम भाव में हो।','पुत्र की प्राप्ति।','','hi'),
('B05_13',5,'५','shubh','लग्नेश और पुत्र-भावेश बलवान् होकर पंचम भाव में बैठे हों।','पुत्रदायक।','','hi'),
('B05_14',5,'६','shubh','चन्द्र, गुरु अथवा शुक्र अपनी उच्च राशि में होकर पंचम भाव में स्थित हों।','पुत्र देते हैं।','','hi'),
('B05_15',5,'६','mrityu','वक्री मङ्गल सुत-भाव (५वें) में हो।','उत्पन्न पुत्र/सन्तान का नाश।','','hi'),
('B05_16',5,'७','shubh','पंचम भाव का स्वामी शुक्र पंचम भाव में ही बैठा हो और वर्षलग्नेश के साथ इत्थशाल करे।','पुत्र देता है।','','hi'),
('B05_17',5,'७','ashubh','शनि का स्थान (जन्म-राशि/पद) पाँचवाँ हो और पंचाधिकारियों में स्थित कोई पापग्रह उसे देखता हो।','पुत्रों को पीड़ा।','','hi'),
('B05_18',5,'८','niyam','जो ग्रह (जन्म में) जिस राशि में हो वह राशि उसका "पद" — वह राशि वर्षकाल में जिस भाव में हो और सबल हो।','उस भाव के शुभ फल देती है; निर्बल हो तो दुःखदायक।','पद-सिद्धान्त — अनेक नियमों का आधार।','hi'),
('B06_01',6,'१','ashubh','वक्री शनि वर्षेश होकर पापग्रहों से युक्त होता हुआ छठे स्थान में हो।','सन्निपात-जन्य मरण-समान क्लेश, शूल, पीड़ा, उदर-रोग, नेत्र-रोग, विषम-ज्वर।','','hi'),
('B06_02',6,'१','ashubh','वर्षेश बृहस्पति वक्री व पापग्रहों से पीड़ित होकर छठे भाव में हो और चन्द्रमा से कम्बूल योग न करे।','वात-विकार से उत्पन्न रोग।','चन्द्र-कम्बूल = अपवाद (भंग)।','hi'),
('B06_03',6,'२','ashubh','मङ्गल वर्षेश होकर पापग्रहों से पीड़ित, वक्री, छठे घर में हो।','रुधिर-विकार से उत्पन्न रोग; पाण्डु/कामला (पीलिया) भी।','','hi'),
('B06_04',6,'२','ashubh','सूर्य वर्ष का स्वामी होकर पाप-पीड़ित छठे भाव में हो।','पित्त-रोग।','वैसा ही सूर्य १२वें स्थान में हो तो नेत्रों में पीड़ा।','hi'),
('B06_05',6,'२','ashubh','शुक्र वर्षेश, पाप-पीड़ित, छठे भाव में हो और उसे षष्ठेश देखे; अथवा शुक्र छठे बैठा हो।','कफ-सम्बन्धी अनेक रोग।','','hi'),
('B06_06',6,'३','ashubh','बुध वर्षेश होकर छठे घर में बैठा हो, वक्री ग्रह तथा पापग्रहों से युक्त हो।','वात-रोग।','','hi'),
('B06_07',6,'३','ashubh','जन्मकालीन लग्नेश पापग्रह होकर वर्तमान वर्षेश से श्रुत-दृष्टि (१,४,७,१०) से देखा जाए।','रोगदायक।','','hi'),
('B06_08',6,'३','mrityu','जन्मलग्नेश पापग्रह होकर पापग्रहों से युक्त हो और वर्षेश उसे श्रुत-दृष्टि से देखे।','मृत्युकारक।','','hi'),
('B06_09',6,'४','ashubh','(शनि-कृत अरिष्ट) जन्म में शनि जिस राशि में हो, वह राशि वर्षप्रवेश के समय लग्न में हो।','पित्त, खुजली, जूड़ी-ज्वर आदि रोग।','','hi'),
('B06_10',6,'४','ashubh','वर्षप्रवेश के समय शनि अपने पद (जन्म-राशि-स्थान) को देखे।','यक्ष्मा (क्षय) रोग।','','hi'),
('B06_11',6,'४','mrityu','शनि पापग्रहों से युक्त होकर जन्मकालीन पाप-युक्त अपने पद को देखे।','मृत्यु।','','hi'),
('B06_12',6,'५','ashubh','मङ्गल जन्म में जिस राशि में हो, वह राशि वर्षलग्न हो और मङ्गल उसे शत्रु (श्रुत १,४,७,१०) दृष्टि से देखे।','रक्त-विकार, पित्त-दोष के रोग, अग्नि-भय तथा और बहुत रोग।','उस लग्न-राशि को शुभग्रह देखें तो शरीर में अल्प रोग।','hi'),
('B06_13',6,'६','ashubh','वर्षलग्नेश, वर्षेश और षष्ठेश का परस्पर (या दो का) इत्थशाल हो।','धातु-विकार से रोग।','','hi'),
('B06_14',6,'६','mishrit','जन्म-शुक्र की राशि वर्षकाल में छठे भाव में हो और उसमें सूर्य बैठा हो; एवं ६/८/१२ में शुक्र हो।','कामी होकर स्त्रियों से रमण।','','hi'),
('B06_15',6,'६','ashubh','रोग-सहम पापग्रहों से युक्त वा दृष्ट हो।','काम-सम्बन्धी रोग — धातु-दोष, उपदंश, मूत्र-रोग, अश्मरी आदि से व्याकुल।','','hi'),
('B06_16',6,'७','ashubh','वर्षप्रवेश के समय पाप-युक्त बृहस्पति वर्षलग्न से आठवें स्थान में हो और मङ्गल वर्षलग्न में हो।','अपस्मार (मिर्गी) रोग से मूर्च्छा।','','hi'),
('B06_17',6,'७','ashubh','चन्द्र-युक्त मङ्गल लग्न में हो और पाप-युक्त गुरु आठवें हो।','अंग-नाश (अवयव-च्छेद)।','','hi'),
('B06_18',6,'७','ashubh','जन्म-समय पापग्रह केन्द्र में हों और वर्षप्रवेश के समय वे ही पापग्रह लग्न में हों।','रोगकारक।','','hi'),
('B06_19',6,'७','ashubh','शुक्र पुरुष (विषम) राशि में विद्यमान हो और पापग्रह देखें।','कफ-जनित रोग।','','hi'),
('B06_20',6,'८','ashubh','दिन में वर्षप्रवेश हो और जन्म तथा वर्ष के लग्न में सूर्य या मङ्गल का द्रेष्काण, हद्दा तथा स्वगृहादि अधिकार हो।','उस वर्ष ज्वर-पीड़ा।','लग्नस्थ मङ्गल-सूर्य को शुभग्रह देखें तो वर्ष के अन्त में सुख।','hi'),
('B06_21',6,'९','shubh','रात्रि में जन्म हो और शुक्ल-पक्ष का चन्द्रमा वर्षकाल में मङ्गल से इत्थशाल करे।','रोग नष्ट हो जाता है।','चन्द्र-शनि इत्थशाल हो तो रोग बढ़ता है।','hi'),
('B06_22',6,'९','ashubh','कृष्ण-पक्ष में जन्म हो और चन्द्रमा मङ्गल से इत्थशाल करे।','रोग की वृद्धि।','शनि से इत्थशाल करे तो रोग नष्ट।','hi'),
('B06_23',6,'१०','ashubh','केतु और बुध के साथ होकर (चन्द्र/ग्रह) सूर्य-मङ्गल से इत्थशाल योग करे।','पूर्ण वर्ष-भर रोगकारक।','','hi'),
('B06_24',6,'१०','ashubh','जन्म में कोई ग्रह किसी भाव/अधिकार में उच्चादि वर्ग से बलिष्ठ हो और वर्षप्रवेश में वही केतु-बुध से युक्त हो।','वर्ष-भर रोगादि होते रहते हैं।','','hi'),
('B06_25',6,'११','ashubh','वर्षप्रवेश-लग्न से चौथे या सातवें स्थान में मुन्था हो और शनि उसे क्रूर-दृष्टि से देखे।','शूल-रोग।','उस मुन्था को पापग्रह देखें तो शूल एक बार नष्ट होकर फिर हो जाए।','hi'),
('B06_26',6,'१२','ashubh','जन्म के बृहस्पति/शुक्र की राशि में मङ्गल, सूर्य के नवांश में हो।','शरीर में छोटी-छोटी फुंसियाँ, शीतला (चेचक), जूड़ी-बुखार, गण्ड-रोग।','','hi'),
('B06_27',6,'१२','ashubh','जन्म-समय की गुरु/शुक्र राशि में चन्द्रमा-सहित बुध हो।','कुष्ठ, भगन्दर तथा गण्डमाला आदि रोग।','','hi'),
('B06_28',6,'१३','ashubh','जन्मलग्नेश और मुन्थेश दोनों वर्षप्रवेश-लग्न से छठे स्थान में हों, हीनबल हों और पापग्रहों से युक्त/दृष्ट हों।','ज्वर, अंग-पीड़ा आदि अनेक कष्ट।','','hi'),
('B06_29',6,'१४','ashubh','मुन्था, वर्षलग्न, मुन्थेश और वर्षलग्नेश — ये चारों पापग्रहों के मध्य में हों।','महारोगदायक।','बीच में एक पापग्रह हो तो भी रोग।','hi'),
('B06_30',6,'१४','shubh','षष्ठेश तथा शुभग्रह छठे भाव में विराजमान हों।','स्त्री की प्राप्ति।','','hi'),
('B06_31',6,'१५','niyam','रोगकारक ग्रह जिस राशि में हो और जिस नवांश में हो — इनमें जो बली हो, उसके राशि-स्वरूप के अनुसार रोग का (शरीर में) स्थान कहें।','रोग-स्थान-निर्णय।','','hi'),
('B06_32',6,'१६','ashubh','जन्म का षष्ठेश मङ्गल हो और वही मङ्गल वर्ष में छठे भाव में बैठा हो।','रोग करता है।','','hi'),
('B06_33',6,'१६','ashubh','मङ्गल छठे भाव में स्थित होकर पापग्रहों के साथ इत्थशाल करे।','कोई बड़ा रोग।','मङ्गल को शुभग्रह देखें या शुभ-युक्त हो तो अल्प रोग।','hi'),
('B07_01',7,'१','shubh','बली शुक्र वर्षेश होकर सातवें भाव में विद्यमान हो।','स्त्री-पक्ष से सुख।','','hi'),
('B07_02',7,'१','shubh','उस शुक्र को गुरु देखे।','बड़ा सुख।','','hi'),
('B07_03',7,'१','shubh','पंचाधिकारियों में से किसी अधिकार में स्थित मङ्गल शुक्र को देखता हो।','पति-पत्नी में परस्पर बहुत प्रीति।','','hi'),
('B07_04',7,'२','mishrit','सप्तमेश शुक्र वर्षेश होकर सातवें भाव में हो और उसे बुध देखे।','अल्पवयस्का स्त्री के साथ छिपी प्रीति।','','hi'),
('B07_05',7,'२','mishrit','शुक्र को शनि देखता हो।','वृद्धा स्त्री के साथ प्रेम।','','hi'),
('B07_06',7,'२','shubh','शुक्र को बृहस्पति देखे।','नवविवाहिता अपनी स्त्री से प्रेम; उससे शीघ्र सन्तान।','','hi'),
('B07_07',7,'३','shubh','जन्मलग्न का स्वामी बली होकर वर्षप्रवेश-लग्न से सातवें भाव में हो।','स्त्री से सुख।','','hi'),
('B07_08',7,'३','shubh','जन्म-शुक्र की राशि वर्षलग्न से सातवीं हो और शुक्र वर्षेश हो।','स्त्री का लाभ।','','hi'),
('B07_09',7,'४','shubh','वर्षलग्न-स्वामी और सप्तमेश का परस्पर इत्थशाल हो।','विवाह द्वारा स्त्री का लाभ।','','hi'),
('B07_10',7,'४','ashubh','स्त्री-सहम का स्वामी या सप्तम भाव का स्वामी नष्टबली (अस्त/पाप-पीड़ित) हो।','स्त्री को कष्ट (रोग)।','','hi'),
('B07_11',7,'५','mishrit','शुक्र-स्थित राशि में हीनबली चन्द्रमा हो।','थोड़ा मैथुन-सुख।','','hi'),
('B07_12',7,'५','shubh','जन्म-शुक्र की राशि पर बली मङ्गल हो।','स्त्री को हर प्रकार का सुख।','','hi'),
('B07_13',7,'६','shubh','जन्मकालीन सप्तमेश वर्षेश शुक्र से युक्त अथवा दृष्ट हो।','विलास व सुख से युक्त स्त्री का समागम।','','hi'),
('B07_14',7,'६','shubh','जन्म-शुक्र-आक्रान्त राशि में बृहस्पति हो और वह वर्ष में केन्द्र (१,४,७,१०) या त्रिकोण (५,९) में बैठा हो; वर्ष-हद्दा का स्वामी व विवाह-सहमेश भी वैसे स्थित हों।','स्त्री-सौख्य कहना चाहिए।','','hi'),
('B07_15',7,'७','ashubh','पंचाधिकारियों में से किसी अधिकारी के स्थान में सूर्य विद्यमान हो।','स्त्री को हमेशा दुःख।','','hi'),
('B07_16',7,'७','shubh','मुन्था किसी अधिकारी के स्थान में हो और उसे बृहस्पति देखे।','विवाह होता है (विवाहिता स्त्री की प्राप्ति)।','कुन्तला: "गुरुदृष्ट्या विवाहकृत्"।','hi'),
('B07_17',7,'८','ashubh','सातवें भाव में सूर्य और मङ्गल के साथ मुन्था विद्यमान हो।','स्त्री तथा पुत्रों से कष्ट।','पापग्रह मुन्था को देखें तो विशेष कष्ट।','hi'),
('B07_18',7,'९','shubh','जन्म का सप्तमेश शुक्र बलवान् होकर (वर्ष में) सातवें भाव में हो और लग्नेश से इत्थशाल करे।','स्त्री-लाभ निश्चित।','','hi'),
('B07_19',7,'१०–११','shubh','मङ्गल वर्षेश हो और उसे शुक्र देखे; अथवा शुक्र वर्षेश हो और मङ्गल देखे।','स्त्री-लाभ।','','hi'),
('B07_20',7,'१०–११','shubh','स्त्री-सहम (दार-सहम) को मङ्गल व शुक्र दोनों देखते हों।','स्त्री का लाभ अवश्य।','स्वामी-दृष्ट व शुक्र-दृष्ट स्त्री-सहम = विवाहकारक।','hi'),
('B07_21',7,'१२','shubh','जन्म का सप्तमेश वर्षप्रवेश-काल में स्त्री-सहम का स्वामी हो तथा सप्तमेश, मुन्थेश और वर्षेश ये तीनों दशम व सप्तम भाव में हों।','स्त्री से सुख की प्राप्ति।','','hi'),
('B07_22',7,'१३','mishrit','अपने घर या अपनी उच्च राशि का चन्द्रमा मुन्था के साथ सप्तम भाव में हो।','विदेश में भ्रमण।','चन्द्रमा को पापग्रह देखें तो कष्ट भी।','hi'),
('B08_01',8,'१','ashubh','मङ्गल वर्षेश होकर क्रूर ग्रहों से पीड़ित व निर्बल होकर किसी भाव में हो।','शरीर के अंग में लोहे का घाव।','','hi'),
('B08_02',8,'१','ashubh','ऐसा मङ्गल अग्नि-तत्त्व राशि (सिंह/धनु आदि) में हो।','अग्नि-भय।','','hi'),
('B08_03',8,'१','mrityu','ऐसा मङ्गल द्विपद (नर) राशि — मिथुन, कन्या, तुला, धनु-पूर्वार्ध — में हो।','उग्र स्वभाव वाले (दुर्जनों) से मृत्यु।','','hi'),
('B08_04',8,'२','ashubh','निर्बल मङ्गल वर्षेश होकर दशम भाव में हो।','राजा, राज-मन्त्री, शत्रु और चोरों से भय।','','hi'),
('B08_05',8,'२','ashubh','पूर्वोक्त मङ्गल चतुर्थ भाव में बैठा हो।','माता, पिता, चाचा, मामा और गुरु — इनसे भय।','','hi'),
('B08_06',8,'३','mrityu','वर्षलग्नेश, मुन्थेश और वर्षेश — ये तीनों आठवें भाव के स्वामी के साथ इत्थशाल करें।','मृत्युकारक।','जन्मकालीन अनिष्ट-ग्रह की दशा-अन्तर्दशा में योग हो तो मरण ही।','hi'),
('B08_07',8,'३','ashubh','दिन में वर्षप्रवेश हो और सूर्य-मङ्गल साथ हों।','राज-भय।','','hi'),
('B08_08',8,'४','ashubh','जन्म-समय शुक्र के साथ सूर्य मूसरिफ योग करे और वही सूर्य पंचाधिकारियों में अधिकार पाकर केन्द्र में हो।','राजा से और रोग से भय।','','hi'),
('B08_09',8,'४','ashubh','जन्मकालीन मङ्गल की राशि पर बुध अधिकारी होकर विराजमान हो।','रोगकारक।','','hi'),
('B08_10',8,'४','ashubh','बुध अधिकारी होकर मङ्गल को पाप-दृष्टि से देखे।','रुधिर-विकार।','','hi'),
('B08_11',8,'४','mrityu','बुध सूर्य की किरणों में स्थित होकर अस्त या दग्ध हो।','विदेश में अथवा कारागार में मृत्यु।','','hi'),
('B08_12',8,'५','ashubh','जिस राशि में (जन्म का) मङ्गल हो, उस राशि पर अधिकार-युक्त चन्द्रमा बैठा हो।','गुप्त राज-भय और रोग।','','hi'),
('B08_13',8,'५','ashubh','शनि अधिकार-प्राप्त होकर दशम भाव में विराजमान हो।','लोहे के प्रहार से पीड़ा।','','hi'),
('B08_14',8,'६','ashubh','वर्षलग्न से आठवें भाव में मङ्गल हो।','अग्नि, हथियार और राजा से भय।','','hi'),
('B08_15',8,'६','ashubh','वर्षलग्न से दशम भाव में मङ्गल हो।','चौपाये (घोड़ा आदि) से गिरकर दुःख; रक्त-विकार से रोगी।','','hi'),
('B08_16',8,'७','ashubh','बृहस्पति वर्षेश होकर दूसरे या आठवें भाव में हो और पापग्रह देखें।','धन का नाश।','','hi'),
('B08_17',8,'७','ashubh','वर्षलग्न से सातवें भाव में शनि बैठा हो।','दुर्वचन, अपवाद (कलंक), कलह और धिक्कार।','','hi'),
('B08_18',8,'८','mrityu','बुध अशुभ (पाप-आक्रान्त) होकर पाप-दृष्टि से देखता हुआ मङ्गल के साथ इत्थशाल करे।','मृत्यु।','दोनों योगों में बुध को शुभग्रह देखें तो शुभ फल।','hi'),
('B08_19',8,'८','ashubh','मङ्गल की हद्दा में (पाप-आक्रान्त बुध) बैठा हो।','द्रव्यादिकों का नाश।','','hi'),
('B08_20',8,'९','ashubh','वर्षलग्नेश नष्टबल होता हुआ अस्त तथा पापग्रहों से युक्त हो।','स्त्री से कलह (स्त्री-विवाद)।','','hi'),
('B08_21',8,'९','ashubh','जन्मलग्न से अष्टम भाव में बृहस्पति हो और वह वर्ष का अधिकारी न हो।','बहुत कलह।','','hi'),
('B08_22',8,'१०','shubh','बृहस्पति शुक्र से देखा जाता हो।','प्रत्युत्तर (जवाब) से विवाद में जय।','','hi'),
('B08_23',8,'१०','ashubh','मङ्गल वर्षलग्न से बारहवें भाव में और सूर्य दूसरे स्थान में बैठा हो।','विवाद से क्लेश।','','hi'),
('B08_24',8,'११','ashubh','वर्षेश मङ्गल से पीड़ित हो।','शत्रुओं और कुटुम्बियों से लड़ाई।','','hi'),
('B08_25',8,'११','ashubh','जन्मलग्न का स्वामी वर्षलग्न से आठवें भाव में हो।','रोग और कलह।','','hi'),
('B08_26',8,'१२','ashubh','जन्म व वर्षकाल में बृहस्पति अधिकारी होकर (जन्मकालीन) मङ्गल की राशि में हो और पापग्रहों से पीड़ित हो।','लोगों के साथ स्फुट (प्रकट) विवाद।','','hi'),
('B08_27',8,'१२','ashubh','जन्म-वर्ष का अधिकारी चन्द्रमा जन्म-समय की शनि-राशि पर स्थित और पापग्रहों से हत हो।','प्रकट कलह।','','hi'),
('B08_28',8,'१३','ashubh','जन्म-वर्ष के अधिकार को प्राप्त चन्द्रमा बुध की (जन्म) राशि में स्थित हो और पापग्रहों से पीड़ित हो।','विदेश-गमन; अन्य जनों के साथ विवाद (वैमनस्य)।','','hi'),
('B08_29',8,'१४','ashubh','मेष, सिंह, धनु — इनमें से किसी राशि में मङ्गल आठवें भाव में स्थित हो।','तलवार (खड्ग) का भय।','','hi'),
('B08_30',8,'१४','mrityu','अष्टम भाव का स्वामी और लग्नेश आठवें भाव में हों और पापग्रहों से दृष्ट अथवा पाप-युक्त हों।','मृत्यु देता है।','','hi'),
('B08_31',8,'१५','ashubh','जन्म में मङ्गल जिस राशि में हो, वही राशि वर्षलग्न हो और बुध वर्षेश व बलरहित होकर विद्यमान हो।','समस्त वर्ष अशुभ।','','hi'),
('B08_32',8,'१६','ashubh','सूर्य-सहित शनि, मङ्गल के साथ वर्षलग्न से आठवें (पाठान्तर: दशम-अष्टम) भाव में बैठा हो।','वाहन से भय।','','hi'),
('B08_33',8,'१६','ashubh','सूर्य-सहित मङ्गल वर्षलग्न के आठवें भाव में हो।','सवारी से गिरने का भय।','','hi'),
('B08_34',8,'१७','mrityu','मङ्गल के साथ वर्षेश आठवें भाव में हो।','मृत्यु।','','hi'),
('B08_35',8,'१७','mrityu','बारहवें, आठवें या छठे — किसी स्थान में चन्द्रमा हो।','मरण होता है।','','hi'),
('B08_36',8,'१७','mrityu','मृत्यु-सहम का स्वामी उदय होकर (कालांश-बहिर्भूत) बलहीन हो।','मृत्यु ("जीवन में मरण-तुल्य कष्ट")।','','hi'),
('B08_37',8,'१८','mrityu','पुण्य-सहम का स्वामी पुण्य-सहम से अष्टम स्थान में हो और पापग्रहों से युक्त व दृष्ट हो।','मरण।','','hi'),
('B08_38',8,'१८','mrityu','जन्मकाल का अष्टमेश वर्षप्रवेश के समय पुण्य-सहम में स्थित हो और पाप-युक्त/पाप-दृष्ट हो।','मृत्यु देने वाला।','','hi'),
('B08_39',8,'१९','mrityu','जन्म-समय लग्न से आठवीं राशि पुण्य-सहम में स्थित होकर अपने स्वामी से युक्त हो।','मृत्यु।','','hi'),
('B08_40',8,'२०','mrityu','पुण्य-सहम पापग्रहों से युक्त हो और अष्टमेश बारहवें/छठे स्थान में हो।','मृत्यु।','','hi'),
('B08_41',8,'२०','mrityu','मुन्था का स्वामी या वर्षेश पापग्रह-युक्त होकर १२, ६, ८ — इनमें से किसी स्थान में हो।','मृत्यु कहें।','','hi'),
('B08_42',8,'२१','mrityu','जन्मलग्न का स्वामी पापग्रहों के साथ आठवें स्थान में हो।','मृत्यु।','','hi'),
('B08_43',8,'२१','mrityu','मुन्था किसी स्थान में शनैश्चर से युक्त हो और उसको मङ्गल शत्रु-दृष्टि (श्रुत १,४,७,१०) से देखे।','आत्मघात से मृत्यु।','','hi'),
('B08_44',8,'२२','mrityu','शनैश्चर आठवें घर में स्थित होकर अष्टमेश के साथ इत्थशाल करे।','मृत्युकारक।','','hi'),
('B08_45',8,'२२','niyam','पूर्वोक्त सम्पूर्ण मृत्यु-योगों में अरिष्टकारक ग्रहों के साथ इत्थशाल हो।','वे अरिष्टकारक ग्रह अशुभ फलदायक होते हैं।','मेटा-नियम।','hi'),
('B08_46',8,'२३','mrityu','जन्म का अष्टमेश शनि वर्षकाल में आठवें स्थान में हो और वर्षेश (लग्नेश) के साथ शत्रु/क्रूर-दृष्टि से इत्थशाल करे।','तत्काल मृत्यु।','','hi'),
('B08_47',8,'२४','mrityu','पुण्य-सहम में चन्द्रमा लग्न में हो और पापग्रह सप्तम में हों; अथवा दो पापग्रह दूसरे व बारहवें में हों; अथवा जन्मलग्नेश और वर्षलग्नेश अष्टम भाव में विराजमान हों।','मरण होता है।','','hi'),
('B09_01',9,'१','shubh','मङ्गल वर्षेश होता हुआ बलवान् हो और वर्षलग्न से तीसरे या नवें भाव में हो।','मार्ग (यात्रा) चलने से लाभ; चिरस्थायी कार्य।','','hi'),
('B09_02',9,'२','shubh','वर्षेश सूर्य कम्बूल योग करता हुआ वर्षलग्न से तीसरे या नवें घर में हो।','यात्रा में सुखदायक।','सूर्य किसी अधिकार में न हो तो किसी अन्य पुरुष द्वारा यात्रा।','hi'),
('B09_03',9,'३','shubh','शुक्र वर्षेश होकर वर्षलग्न से तीसरे/नवें घर में हो।','मार्ग में सुख।','यात्रा से पहले शुक्र वक्री या अस्त हो जाए तो गमन ठीक नहीं।','hi'),
('B09_04',9,'३','shubh','बुध वर्षेश और बलवान् होकर तीसरे/नवें भाव में स्थित हो।','देव-दर्शन (तीर्थ) के उद्देश्य से यात्रा।','','hi'),
('B09_05',9,'४','ashubh','वैसा वर्षपति बुध पाप-पीड़ित हो।','कु-यात्रा (हानिकर गमन)।','','hi'),
('B09_06',9,'४','shubh','बृहस्पति वर्षेश होकर वर्षलग्न से तीसरे/नवें स्थान में बली व पाप-रहित हो।','धर्म-यात्रा।','गुरु वर्षेश पाप-पीड़ित/पाप-युक्त हो तो कु-यात्रा।','hi'),
('B09_07',9,'४','mishrit','वर्षलग्नेश के साथ नवम भाव के स्वामी का इत्थशाल हो।','अचिन्तित (आकस्मिक) यात्रा — परदेश-गमन।','','hi'),
('B09_08',9,'५','mishrit','लग्नेश नवमेश के दीप्तांश के भीतर होकर स्थित हो (धर्म को स्व-तेज देता हुआ)।','चिन्ता-युक्त मार्ग-गमन।','लग्नेश-वर्षेश योग अथवा मुन्थेश-वर्षलग्नेश का मुथशिल हो तो भी चिन्तित गमन।','hi'),
('B09_09',9,'६','shubh','जन्मकालीन बृहस्पति की राशि में मङ्गल हो और वह वर्षलग्न से नवम भाव में हो।','यात्रा में सेवक और धन की प्राप्ति; शुभ यात्रा।','','hi'),
('B09_10',9,'६','shubh','जन्म में बुध जिस राशि में हो, उस राशि में वर्ष-समय मङ्गल हो और उसे वर्षलग्न-स्वामी देखे।','समीचीन यात्रा; उत्तम सवारी तथा सौख्य।','','hi'),
('B09_11',9,'७','shubh','मङ्गल अपने घर (मेष/वृश्चिक) में, वर्षकाल में अपनी राशि पर बली होकर लग्न को देख रहा हो और नवम घर में स्थित हो।','सुन्दर यात्रा; अच्छी सवारी।','','hi'),
('B09_12',9,'७–८','ashubh','बुध अधिकारी होकर शनि की राशि में नवम स्थान में बैठा हो और पापग्रहों से युक्त हो।','शत्रु के कारण यात्रा।','','hi'),
('B09_13',9,'७–८','ashubh','चन्द्रमा के घर में बृहस्पति आदि अधिकारी होकर जन्मकालीन शनि-राशि में, नवम स्थान में, पाप-युक्त हो।','शत्रु के साथ कलह से बहुत दूर की यात्रा।','','hi'),
('B09_14',9,'८','ashubh','वर्षकाल में शनि पंचाधिकारों से रहित होकर नवम भाव में विद्यमान हो।','यात्रा अशुभ अर्थात् हानिकर।','','hi'),
('B09_15',9,'९','shubh','बृहस्पति अधिकार-हीन होकर नवम स्थान में हो।','राजा के साथ दूर-गमन; उस यात्रा में राज-संग से द्रव्य-लाभ।','','hi'),
('B09_16',9,'९','ashubh','मङ्गल वर्षेश होकर पंचवर्गीय बल से नष्टबली हो और वर्षलग्न से नवम स्थान में स्थित हो।','अपने कुटुम्ब-वर्ग से दूर रहना पड़ता है।','','hi'),
('B09_17',9,'१०','shubh','सप्तम भाव में मुन्था और नवम भाव में बलवान् चन्द्रमा हो।','विदेश की यात्रा लाभदायक।','','hi'),
('B09_18',9,'१०–११','shubh','वर्षेश बलवान्, पाप-योग-रहित तथा अधिकारी होकर केन्द्र (१,४,७,१०) में स्थित हो।','रणभूमि में सेनापति होकर गमन।','','hi'),
('B09_19',9,'११–१२','shubh','बुध और मङ्गल बलिष्ठ व उदित बृहस्पति से युक्त होकर केन्द्र में हों।','शत्रु-सेना पर धावा; जय, ख्याति और सुख।','','hi'),
('B09_20',9,'१२','shubh','वर्षप्रवेश-काल में बृहस्पति के साथ मङ्गल नवम स्थान में विद्यमान हो।','मनुष्यों की शुभ यात्रा।','','hi'),
('B10_01',10,'१','shubh','बल-सहित वर्षेश दशम भाव में विद्यमान हो।','राज्य, धन, सुख और कीर्ति — सब प्राप्त।','','hi'),
('B10_02',10,'१','shubh','अन्य ग्रह केन्द्र (१,४,७,१०) में बैठे हों।','घर की प्राप्ति और गृह-सुख।','','hi'),
('B10_03',10,'२','shubh','वर्ष का मालिक बलवान् होकर वर्षलग्न से चौथे घर में बैठा हो।','पूर्वार्जित पद/स्थान का लाभ; राजा और उत्तम मन्त्रि-गणों से मित्रता।','कुन्तला: बली वर्षेश सूर्य ११वें हो तो भूप-मन्त्रि-प्रधानों से मैत्री।','hi'),
('B10_04',10,'३','shubh','जन्म-समय सूर्य-स्थित राशि (वर्ष) लग्न में हो और मुन्था दशम भाव में बैठी हो।','राज्य और सुख।','','hi'),
('B10_05',10,'३','mrityu','सूर्य नीच राशि (तुला) में, पापग्रहों से युक्त और वर्षलग्न से दशम स्थान में हो।','राजा की आज्ञा से बन्धन और वध।','','hi'),
('B10_06',10,'४','shubh','सिंह राशि का बलवान् सूर्य दशम स्थान में बैठा हो।','स्थान-लाभ; राजा का आश्रय।','जन्म-समय बलवान् चन्द्रमा हो तो अन्य स्थान में अधिकार-प्राप्ति।','hi'),
('B10_07',10,'५','shubh','दशम भाव का स्वामी, वर्षलग्न-स्वामी और वर्षेश — तीनों का परस्पर इत्थशाल हो।','राज्य मिलता है।','','hi'),
('B10_08',10,'५','shubh','वर्षेश राज्य-सहम में स्थित होकर सूर्य के साथ इत्थशाल करे।','बड़ा भारी राजा (महानृप) होता है।','','hi'),
('B10_09',10,'६','ashubh','जन्म-समय की शनैश्चर-राशि पर मङ्गल वर्षलग्न से दशम घर में हो और वह मुन्था को देखता हो।','पाप-कर्म से राज-भय; धन की हानि।','','hi'),
('B10_10',10,'७','ashubh','मङ्गल शनि की राशि में बैठा हो, वर्षप्रवेश उसी राशि पर हो और अस्तंगत व बलरहित शनि वर्षलग्न से तीसरे/नवें भाव में हो।','पाप-वृद्धि से क्लेश।','','hi'),
('B10_11',10,'७','shubh','शनि वर्षेश अथवा अधिकारी होकर वर्षलग्न से तीसरे/नवें भाव में हो।','धर्म की वृद्धि; सुख की प्राप्ति।','','hi'),
('B10_12',10,'८','ashubh','वर्षेश (शनि) अधिकारी होकर दग्ध (अस्तंगत) या बलरहित हो और वर्षलग्न से तीसरे/नवें भाव में हो।','मनुष्य पापी और धर्म-निन्दक (नास्तिक) होता है।','सूर्य वर्षेश-अधिकारी अस्त-निर्बल हो तो भी यही फल।','hi'),
('B10_13',10,'८','mishrit','बृहस्पति वर्षेश-अधिकारी दग्ध या बलरहित होता हुआ वर्षलग्न से तीसरे/नवें में स्थित हो।','नीति-मार्ग से धन पाता है।','','hi'),
('B10_14',10,'९','shubh','तीसरे या नवें घर में मुन्था हो।','पुण्य का लाभ।','मुन्था को पापग्रह देखें/पाप-युक्त हो तो पाप-फल।','hi'),
('B10_15',10,'९–१०','shubh','जन्मलग्न से दशम भाव का स्वामी (सूर्यादि) वर्ष में दशम घर में बैठा हो और वर्षलग्न-स्वामी के साथ इत्थशाल हो।','बलानुसार राज्य की प्राप्ति।','','hi'),
('B10_16',10,'१०','ashubh','धर्म-भाव (९) का स्वामी दग्ध (अस्तंगत) हो।','धर्म का क्षय।','','hi'),
('B10_17',10,'१०','ashubh','दशम भाव का स्वामी दग्ध हो।','राज्य का नाश।','','hi'),
('B11_01',11,'१','shubh','बुध वर्ष का स्वामी होकर वर्षलग्न से दूसरे स्थान में हो और शुभग्रह देखें या शुभ-युक्त हो।','व्यापार-कर्म से लाभ।','','hi'),
('B11_02',11,'१','shubh','वर्ष-स्वामी बुध शुभग्रहों से युक्त व दृष्ट होकर मुन्था-सहित वर्षलग्न में बैठा हो।','लिखने-पढ़ने से धन-लाभ।','','hi'),
('B11_03',11,'२','ashubh','बुध वर्षलग्न से छठे, आठवें, बारहवें — इनमें से किसी स्थान में हो और पापग्रहों से युक्त हो।','नीच कर्म करने वाला होता है।','','hi'),
('B11_04',11,'२','ashubh','बुध वर्षेश होकर ६/८/१२ भाव में हो और पापग्रहों से देखा जाता हो या अस्तंगत हो।','लिखने-पढ़ने से लाभ नहीं होता।','','hi'),
('B11_05',11,'३','ashubh','बृहस्पति वर्षेश हो और पापग्रह से पीड़ित होकर वर्षलग्न में हो।','धन की हानि; राजा से भय।','','hi'),
('B11_06',11,'३','shubh','वर्षेश बृहस्पति उच्चाधिकार आदि को प्राप्त होकर वर्षलग्न से सातवें घर में हो।','वाणिज्य से धन का उत्तम लाभ।','','hi'),
('B11_07',11,'४','shubh','लग्नेश और लाभेश (११वें के स्वामी) का परस्पर इत्थशाल योग हो।','लाभ; अपने जनों से मान।','','hi'),
('B11_08',11,'४','shubh','सब ग्रह बली होकर लाभ-स्थान (११) में हों।','द्रव्य की प्राप्ति।','सब ग्रह निर्बल होकर लाभ-भाव में हों तो धन-प्राप्ति नहीं।','hi'),
('B11_09',11,'५','shubh','बलवान् बुध मुन्था-सहित वर्षलग्न में हो और शुभग्रह धन-सहम (अर्थ-सहम) में हों।','गड़े हुए (निखात) द्रव्य का लाभ।','इस योग पर पापग्रहों की दृष्टि हो तो गड़ा धन कदापि नहीं मिलता।','hi'),
('B12_01',12,'१–२','ashubh','वर्षलग्नेश और वर्षेश दोनों बलहीन होकर १२, ६, ८ — इनमें से किसी स्थान में हों।','जिस राशि पर स्थित हों, उसी के अनुसार हानि — जल-राशि में जलचर की, नर-राशि में सेवक-जनों की, चतुष्पद-राशि में चौपायों की हानि।','','hi'),
('B12_02',12,'१–२','ashubh','वर्षेश शुक्र छठे भाव में, बलरहित, पापग्रहों की श्रुत (१,४,७,१०) दृष्टि से युक्त, द्विपद राशि में स्थित हो।','सेवकों का नाश।','शुक्र चतुष्पद राशि में हो तो घोड़ा आदि चौपायों की हानि।','hi'),
('B12_03',12,'१–२','ashubh','अन्य कोई ग्रह वर्षेश होकर ६/८/१२ स्थानों में द्विपद राशियों में हो।','पूर्वोक्त (सेवक-नाश आदि) फल।','','hi'),
('B12_04',12,'१–२','ashubh','वर्ष-स्वामी मङ्गल शनि (पाठ: चन्द्रमा) से युक्त होकर वर्षलग्न से दशम भाव में हो।','घोड़े आदि का नाश; मन में व्यग्रता बनी रहती है।','','hi'),
('B12_05',12,'३','ashubh','वर्षेश पापग्रहों से युक्त होकर चतुष्पद राशि में छठे, आठवें अथवा बारहवें घर में बैठा हो।','सेवकों के साथ कलह।','','hi'),
('B12_06',12,'३','mishrit','वर्ष का स्वामी बल-सहित चन्द्र हो और छठे/आठवें (रिपु-रिःफ) स्थान में स्थित हो।','उजड़ी भूमि में बसता हुआ बाग, कुआँ, तालाब आदि का निर्माण करता है।','','hi'),
('B12_07',12,'४','shubh','शनैश्चर वर्षेश होकर अपनी राशि (मकर/कुम्भ) या उच्च (तुला) में हो और वर्षलग्न से दशम भाव में हो।','शरीर की आरोग्यता और धन की प्राप्ति।','बृहस्पति वैसा हो तो भी आरोग्य व धन।','hi'),
('B12_08',12,'४','shubh','सूर्य वर्षेश होकर अपनी राशि (सिंह)/उच्च में दशम भाव में विद्यमान हो।','राजा से धन प्राप्त।','','hi'),
('B12_09',12,'४','shubh','मङ्गल वर्षेश होकर अपनी राशि व उच्च में दशम भाव में हो।','अपने भुज-बल से धन।','','hi'),
('B12_10',12,'४','shubh','बुध वर्षेश होकर अपनी राशि व उच्च राशि में दशम भाव में विराजमान हो।','वैदिक (वैद्यक), ज्योतिष, कविता और कारीगरी आदि से धन-लाभ।','','hi'),
('B12_11',12,'५','ashubh','शनैश्चर वर्षेश हो किन्तु बलहीन होकर वर्षलग्न से दसवें भाव में हो।','आशाहीन और चंचल चित्त।','','hi'),
('B12_12',12,'५','ashubh','वर्ष-स्वामी सूर्य हो और शनैश्चर जन्म-वर्ष दोनों समय चन्द्र-राशि पर बलरहित बैठा हो।','सब कामों में विफल और सामर्थ्य-रहित।','शनि वक्री या अस्तंगत हो तो भी यही फल।','hi'),
('B12_13',12,'६','ashubh','दशम भाव, दशम-भावेश और कर्म-सहमेश — तीनों शनैश्चर से युक्त या दृष्ट हों।','सब कार्यों में असफलता मिलती रहे।','','hi'),
('B12_14',12,'७','ashubh','वर्षेश निर्बल होकर वर्षलग्न से ६/८/१२ भाव में हो तथा दशमेश जन्म-वर्ष दोनों में निर्बल होकर ६/८/१२ भावों में हो।','कल्याण नहीं होता।','','hi'),
('B12_15',12,'७','ashubh','अष्टम भाव का स्वामी छठे, आठवें या बारहवें स्थान में हो।','मङ्गलकारक नहीं।','','hi'),
('B12_16',12,'८','niyam','जिस भाव में शुभ या अशुभ फल देने वाला कोई ग्रह जन्म में हो, वही ग्रह वर्षकाल में उसी के समान (अवस्था में) उसी भाव में बैठा हो।','उस भाव का शुभ/अशुभ फल अवश्य देता है।','','hi'),
('B12_17',12,'९','niyam','जो ग्रह जन्म में बलवान् और वर्षप्रवेश में बलहीन हों।','वर्ष के पूर्वार्ध में शुभ, उत्तरार्ध में अशुभ फल।','विपरीत में विपरीत; समान बल हो तो सम्पूर्ण वर्ष समान फल।','hi'),
('B12_18',12,'१०','niyam','उपसंहार-श्लोक: गर्ग-वंश — चिन्तामणि दैवज्ञ, पुत्र अनन्त दैवज्ञ (जन्म-पद्धति के रचयिता), उनके पुत्र नीलकण्ठ — गुरु पं॰ शिवदैवज्ञ की आज्ञा से बारह भावों का यह विचार।','ग्रन्थकार-वंश-परिचय (कोई फलादेश-नियम नहीं)।','उपसंहार।','hi')
