-- =============================================================================
-- Auto Business — Tajik-Neelakanthi Bhava-Phal rules (migration 023)
-- All 262 bhava-phal rules (Neelakantha Daivajna, Varshatantra, Bhava-vichara-
-- adhyaya, pp. 180-224). DB rows override the baked TajikBhavaData by rule_id;
-- the engine auto-marks the computable subset against the varsha chart.
-- Additive "भाव-फल" option in the Varshaphal prediction dropdown.
-- Source: docs/tajik_neelakanthi_bhava_phal_niyam.md.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS tajik_bhava_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    rule_id VARCHAR(12) NOT NULL,
    house TINYINT NOT NULL,
    shloka VARCHAR(24) NOT NULL,
    category VARCHAR(12) NOT NULL,          -- shubh/ashubh/mrityu/mishrit/niyam
    cond_text TEXT NOT NULL,
    phal_text TEXT NOT NULL,
    note_text TEXT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi',
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_tbp (rule_id, language), KEY idx_house (house)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE house=VALUES(house), shloka=VALUES(shloka), category=VALUES(category),
    cond_text=VALUES(cond_text), phal_text=VALUES(phal_text), note_text=VALUES(note_text);

-- Config toggles (additive; engine defaults to '1' when absent).
ON DUPLICATE KEY UPDATE cfg_value=VALUES(cfg_value);
